ity, no reduction, B/W, and with gap.;	DC.W f1+f2+f3+f6	wDev           equ	0	DC.W 1320	iPageV         equ	2	DC.W 1020	iPageH         equ	4	DC.W 0	bPort          equ	6	DC.W 1	feed           equ	8	DC.W 0	PaperType      equ	10	DC.W 960	CRwidth        equ	12	DC.W 0	reserved	DC.W 0*prInfoPT       equ	 42       SubRecord	DC.W iDevEpson	*idev           equ	 0	DC.W 36	*iVRes          equ	 2	DC.W 80	*iHRes          equ	 4	DC.W 0,0,396,640	*rPage          equ	 6*prXInfo        equ	 56       SubRecord	DC.W 80	iRowBytes      equ	0	DC.W 32	iBandV         equ	2	DC.W 640	iBandH         equ	4	DC.W 10240	iDevBytes      equ	6	DC.W 12	ibands         equ	8	DC.B 0	bPatScale      equ	10	DC.B 1	bULThick       equ	11	DC.B 1	bULOffset      equ	12	DC.B 1	bULShadow      equ	13	DC.B 0	scan           equ	14	DC.B 0	bXInfoX        equ	16	DCB.B 8,0	reserved*prJob          equ	 80       SubRecord* TPrJob subrecord length = 20 bytes	DC.W 1	iFstPage       equ	0	DC.W 9999	iLstPage       equ	2	DC.W 1	iCopies        equ	4	DC.B $80	bjDocLoop      equ	6	DC.B 1	fFromUsr       equ	7	DC.L 0	pIdleProc      equ	8	DC.L 0	pFileName      equ	12	DC.W 0	iFileVol       equ	16	DC.B 0	bFileVers      equ	18	DC.B 0	bJobX          equ	19*printx         equ	 100      Array[1..19] of integer (38 bytes)	DC.W 0	plus two reserved bytes	DC.W 0	DC.W 0	DC.W 0	DC.W 0	DC.W 0	DC.W 0	DC.W 0	DC.W 0	DC.W 0	DC.W 0	DC.W 0	DC.W 0	DC.W 0	DC.W 0	DC.W 0	DC.W 0	DC.W 0	DC.W 0	DC.W 0*TPrintsize     equ	 140	EXPORT GapGap	DC.W 0	DC.W 60	EXPORT PortVresPortVres	DC.W 36	EXPORT PortHresPortHres	DC.W 40	DC.W 80	Export LandVresLandVres	DC.W 40	Export LandHresLandHres	DC.W 36	DC.W 72	EXPORT PaperVsizePaperVsize	DC.W 1320	DC.W 1680	DC.W 1400	DC.W 1440	EXPORT PaperHsizePaperHsize	DC.W 1020	DC.W 1020	DC.W 990	DC.W 990	EXPORT CarriageWidthCarriageWidth	DC.W 960	DC.W 960	DC.W 960	DC.W 960* US Letter/640 portrait gap:	    36 80 0 0 378 640  -9 -20 